import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Page Loading","description":"","frontmatter":{"prev":{"text":"Insert & Remove HTML","link":"/documentation/field-types/others/insert-remove-html"},"next":{"text":"Toast Notification","link":"/documentation/field-types/others/toast-notification"}},"headers":[],"relativePath":"documentation/field-types/others/page-loading.md","filePath":"documentation/field-types/others/page-loading.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/others/page-loading.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="page-loading" tabindex="-1">Page Loading <a class="header-anchor" href="#page-loading" aria-label="Permalink to “Page Loading”">​</a></h1><p>Synchronize automated workflows with dynamic single-page applications by waiting for spinners, progress bars, or loading overlays to appear and finish.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Modern web applications frequently rely on AJAX requests, asynchronous calculations, and dynamic loaders. Interacting with inputs while a page is still loading can lead to dropped inputs or race conditions. The <strong>Page Loading</strong> field type pauses automation until loading indicators mount, resolve, and disappear cleanly from the screen.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Selector Query</strong></td><td>Text Input</td><td>CSS selector or XPath of the loading spinner or overlay element.</td><td>Yes</td></tr><tr><td><strong>Loading Behavior</strong></td><td>Toggle Selection</td><td>Evaluation rule for the loading indicator lifecycle.</td><td>Yes</td></tr><tr><td><strong>Timeout (Milliseconds)</strong></td><td>Number Input</td><td>Maximum wait time before continuing or throwing a timeout.</td><td>Conditional</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Mutual Exclusivity</strong>: Choose only one loading behavior rule per field to maintain deterministic lifecycle checks.</p></div><hr><h2 id="behaviors" tabindex="-1">Loading Behavior Rules <a class="header-anchor" href="#behaviors" aria-label="Permalink to “Loading Behavior Rules”">​</a></h2><h3 id="option-1-first-check-loading-is-visible-then-hidden" tabindex="-1">Option 1: First Check Loading is Visible, Then Hidden <a class="header-anchor" href="#option-1-first-check-loading-is-visible-then-hidden" aria-label="Permalink to “Option 1: First Check Loading is Visible, Then Hidden”">​</a></h3><ul><li><strong>Description</strong>: Waits for the loading spinner to <strong>appear</strong> (visible on screen), and then waits for it to <strong>disappear</strong> (hidden or unmounted).</li><li><strong>Ideal For</strong>: Button clicks or dropdown selections that trigger an immediate AJAX spinner that vanishes upon completion.</li></ul><h3 id="option-2-wait-until-loading-is-hidden" tabindex="-1">Option 2: Wait Until Loading is Hidden <a class="header-anchor" href="#option-2-wait-until-loading-is-hidden" aria-label="Permalink to “Option 2: Wait Until Loading is Hidden”">​</a></h3><ul><li><strong>Description</strong>: Waits exclusively for an already visible or initial page loading overlay to disappear.</li><li><strong>Ideal For</strong>: Initial page load screens or full-screen splash masks that are present on load.</li></ul><h3 id="option-3-wait-until-loading-appears" tabindex="-1">Option 3: Wait Until Loading Appears <a class="header-anchor" href="#option-3-wait-until-loading-appears" aria-label="Permalink to “Option 3: Wait Until Loading Appears”">​</a></h3><ul><li><strong>Description</strong>: Waits for an indicator to become visible.</li><li><strong>Ideal For</strong>: Verification checkpoints ensuring that a background operation was acknowledged by the server.</li></ul><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-form-submission-spinner-sync" tabindex="-1">Example 1: Form Submission Spinner Sync <a class="header-anchor" href="#example-1-form-submission-spinner-sync" aria-label="Permalink to “Example 1: Form Submission Spinner Sync”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Selector Query: .spinner-border, #loading-overlay</span></span>
<span class="line"><span>Loading Behavior: First check loading is visible, then hidden</span></span>
<span class="line"><span>Timeout: 15000 (15 seconds)</span></span></code></pre></div><h3 id="example-2-initial-dashboard-data-hydration" tabindex="-1">Example 2: Initial Dashboard Data Hydration <a class="header-anchor" href="#example-2-initial-dashboard-data-hydration" aria-label="Permalink to “Example 2: Initial Dashboard Data Hydration”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Selector Query: div[data-testid=&quot;page-loading-skeleton&quot;]</span></span>
<span class="line"><span>Loading Behavior: Wait until loading is hidden</span></span>
<span class="line"><span>Timeout: 20000 (20 seconds)</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><h3 id="do-s" tabindex="-1">Do&#39;s <a class="header-anchor" href="#do-s" aria-label="Permalink to “Do&#39;s”">​</a></h3><ul><li><strong>Inspect Dynamic Visibility</strong>: Check whether the web application toggles <code>display: none</code>, <code>visibility: hidden</code>, or unmounts the node completely from the DOM.</li><li><strong>Set Generous Timeouts</strong>: Set realistic timeouts (e.g., 10,000–30,000 ms) for slow backend endpoints or heavy data queries.</li><li><strong>Combine with Element Wait</strong>: If the spinner itself mounts with a delay, add a small delay before running the field.</li></ul><h3 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to “Don&#39;ts”">​</a></h3><ul><li><strong>Do Not Target Static Containers</strong>: Ensure the selector points strictly to the indicator that changes state, not its parent page container.</li><li><strong>Do Not Leave Timeout Unset on Fragile Networks</strong>: Always define a timeout to prevent workflows from hanging indefinitely if a server request drops.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Timeout exceeded waiting for visibility</strong></td><td>Spinner resolved faster than the field executed</td><td>Switch behavior to <strong>Wait until loading is hidden</strong>.</td></tr><tr><td><strong>Never detects hidden state</strong></td><td>Loader opacity set to 0 without changing <code>display</code> or removing node</td><td>Inspect element CSS properties or target a more specific child indicator.</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html#timing-position-settings">Field Settings Timing Delays</a></li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs</a></li></ul>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};